// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address candidateNewOwner) public {
        vm.assume(caller != address(0));

        address beforeOwner = c.owner();

        bool ok;
        try c.transferOwnership{gas: gasleft()}(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller == beforeOwner) {
            vm.prank(caller);
            bool ok2;
            try c.transferOwnership(candidateNewOwner) {
                ok2 = true;
            } catch {
                ok2 = false;
            }

            assertTrue(c.owner() == candidateNewOwner);
        } else {
            assertTrue(c.owner() == beforeOwner);
        }
    }
}
